/* CSS PART 1 OF 2 */

:root {
  --color-ink: #263238;
  --color-paper: #f7f5ef;
  --color-accent: #c47b52;
  --color-muted: #e8e2d8;
  --content-width: 1100px;
}

body {
  margin: 0;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: system-ui, sans-serif;
  line-height: 1.6;
}

.site-header {
  padding: 20px 6%;
  background: var(--color-paper);
  border-bottom: 1px solid var(--color-muted);
}

.hero {
  padding: 96px 6%;
  background: var(--color-muted);
  text-align: center;
}
